package com.learn.hub.order.domain;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/** 聚合根：状态只能经由业务方法改变，行项目不向外暴露可变集合。 */
public final class Order {

    private final String id;
    private final List<Line> lines = new ArrayList<>();
    private Status status = Status.CREATED;

    public Order(String id) { this.id = id; }

    public void addLine(String sku, BigDecimal price, int quantity) {
        if (status != Status.CREATED) {
            throw new IllegalStateException("已提交的订单不能再改行项目");
        }
        if (quantity <= 0 || price.signum() < 0) {
            throw new IllegalArgumentException("数量与单价必须为正");
        }
        lines.add(new Line(sku, price, quantity));
    }

    public BigDecimal total() {
        return lines.stream()
                .map(line -> line.price().multiply(BigDecimal.valueOf(line.quantity())))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public void submit() {
        if (lines.isEmpty()) {
            throw new IllegalStateException("空订单不能提交");
        }
        status = Status.SUBMITTED;
    }

    public String id() { return id; }

    public enum Status { CREATED, SUBMITTED, CANCELLED }

    public record Line(String sku, BigDecimal price, int quantity) { }
}

package com.learn.hub.order.adapter;

import com.learn.hub.order.domain.Order;
import com.learn.hub.order.domain.OrderRepository;
import java.util.Optional;
import org.springframework.stereotype.Repository;

/** 领域只定义端口，JPA 与行结构都锁在这个适配器里。 */
@Repository
class JpaOrderRepository implements OrderRepository {

    private final OrderJpaRepository jpa;

    JpaOrderRepository(OrderJpaRepository jpa) {
        this.jpa = jpa;
    }

    @Override
    public Optional<Order> byId(String id) {
        return jpa.findByBusinessId(id).map(this::toDomain);
    }

    @Override
    public void save(Order order) {
        OrderRow row = jpa.findByBusinessId(order.id())
                .orElseGet(() -> new OrderRow(order.id()));
        row.apply(order);
        jpa.save(row);
    }

    private Order toDomain(OrderRow row) {
        Order order = new Order(row.getBusinessId());
        row.getLines().forEach(line -> order.addLine(line.sku(), line.price(), line.quantity()));
        if ("SUBMITTED".equals(row.getStatus())) {
            order.submit();
        }
        return order;
    }
}

export type OrderEvent =
  | { type: 'order.placed'; orderId: string; total: number }
  | { type: 'order.paid'; orderId: string }
  | { type: 'order.cancelled'; orderId: string };

export interface OrderRow {
  orderId: string;
  total: number;
  status: 'placed' | 'paid' | 'cancelled';
}

/** 读模型只认事件，不反查写库；同一事件重放两次必须得到同一结果。 */
export function project(state: Map<string, OrderRow>, event: OrderEvent): Map<string, OrderRow> {
  const next = new Map(state);
  switch (event.type) {
    case 'order.placed':
      next.set(event.orderId, { orderId: event.orderId, total: event.total, status: 'placed' });
      break;
    case 'order.paid': {
      const row = next.get(event.orderId);
      if (row?.status === 'placed') next.set(event.orderId, { ...row, status: 'paid' });
      break;
    }
    case 'order.cancelled': {
      const row = next.get(event.orderId);
      if (row && row.status !== 'cancelled') next.set(event.orderId, { ...row, status: 'cancelled' });
      break;
    }
  }
  return next;
}
